class Solution {
    public int removeDuplicates(int[] nums) {
        int n = nums.length;
        int slow = 0;
        int[] count = new int[20001];  // 值范围 [-10^4, 10^4]
        for (int fast = 0; fast < n; fast++) {
            int v = nums[fast] + 10000;  // 偏移映射到非负数组下标
            if (count[v] < 2) {
                nums[slow++] = nums[fast];
                count[v]++;
            }
        }
        return slow;
    }
}

class Solution {
    public int removeDuplicates(int[] nums) {
        int n = nums.length;
        if (n <= 2) return n;  // 长度 <= 2，天然满足条件

        int slow = 2;  // 前两个元素已保留，从下标 2 开始写
        for (int fast = 2; fast < n; fast++) {
            // 当前元素 ≠ 往前数第 2 个保留元素 → 不会构成 3 连，可保留
            if (nums[fast] != nums[slow - 2]) {
                nums[slow] = nums[fast];
                slow++;
            }
            // 相等 → 说明已有 2 个重复，当前跳过
        }
        return slow;
    }
}

class Solution {
    public int removeDuplicates(int[] nums) {
        int k = 2;                 // 允许最多出现的次数
        int n = nums.length;
        if (n <= k) return n;
        int slow = k;
        for (int fast = k; fast < n; fast++) {
            if (nums[fast] != nums[slow - k]) {
                nums[slow++] = nums[fast];
            }
        }
        return slow;
    }
}

