import java.util.Arrays;

class Solution {
    public void merge(int[] nums1, int m, int[] nums2, int n) {
        // 把 nums2 拷到 nums1 尾部
        for (int i = 0; i < n; i++) {
            nums1[m + i] = nums2[i];
        }
        Arrays.sort(nums1);
    }
}

class Solution {
    public void merge(int[] nums1, int m, int[] nums2, int n) {
        int[] temp = new int[m + n];
        int i = 0, j = 0, k = 0;
        // 归并两个有序数组
        while (i < m && j < n) {
            if (nums1[i] <= nums2[j]) {
                temp[k++] = nums1[i++];
            } else {
                temp[k++] = nums2[j++];
            }
        }
        // 把剩余元素拷进去（两个 while 最多执行一个）
        while (i < m) temp[k++] = nums1[i++];
        while (j < n) temp[k++] = nums2[j++];
        // 拷回 nums1
        for (int t = 0; t < m + n; t++) {
            nums1[t] = temp[t];
        }
    }
}

class Solution {
    public void merge(int[] nums1, int m, int[] nums2, int n) {
        int p1 = m - 1;           // nums1 有效部分末尾
        int p2 = n - 1;           // nums2 末尾
        int p = m + n - 1;        // 填入位置
        // 从后往前，把较大的元素放到 nums1 尾部
        while (p2 >= 0) {         // 只需判断 p2: nums2 没搬完就继续
            if (p1 >= 0 && nums1[p1] > nums2[p2]) {
                nums1[p] = nums1[p1]; // nums1 的更大，搬它
                p1--;
            } else {
                nums1[p] = nums2[p2]; // nums2 的更大（或 nums1 搬完了）
                p2--;
            }
            p--;
        }
        // 如果 nums2 搬完了，nums1 剩余部分已经在正确位置，无需处理
    }
}

