import java.util.*;

class Solution {
    public List<Integer> getRow(int rowIndex) {
        List<Integer> prev = new ArrayList<>();
        prev.add(1);  // 第 0 行

        for (int i = 1; i <= rowIndex; i++) {
            List<Integer> curr = new ArrayList<>();
            curr.add(1);                                  // 首
            for (int j = 1; j < i; j++) {
                curr.add(prev.get(j - 1) + prev.get(j));  // 中间
            }
            curr.add(1);                                  // 尾
            prev = curr;  // 交换引用
        }
        return prev;
    }
}

import java.util.*;

class Solution {
    public List<Integer> getRow(int rowIndex) {
        List<Integer> row = new ArrayList<>();
        row.add(1);  // 第 0 行

        for (int i = 1; i <= rowIndex; i++) {
            // 行尾追加 1
            row.add(1);

            // 从右往左更新中间元素（跳过首尾的下标 0 和 i）
            for (int j = i - 1; j > 0; j--) {
                row.set(j, row.get(j) + row.get(j - 1));
            }
            // row[0] 始终是 1，不用改
        }
        return row;
    }
}

// 组合数解法（空间 O(1)，仅作展示）
class Solution {
    public List<Integer> getRow(int rowIndex) {
        List<Integer> row = new ArrayList<>();
        long val = 1;  // C(k, 0) = 1
        row.add((int) val);
        for (int i = 1; i <= rowIndex; i++) {
            val = val * (rowIndex - i + 1) / i;  // C(k,i) = C(k,i-1) * (k-i+1) / i
            row.add((int) val);
        }
        return row;
    }
}

